mapper.update:
UPDATE t_deposit_refund
SET status = #{status},
    admin_remark = #{adminRemark},
    handle_time = NOW(),
    handle_by = #{adminId}
WHERE id = #{id}

choose.when:
SELECT r.*, u.username, u.real_name
FROM t_deposit_refund r LEFT JOIN t_user u ON r.user_id = u.id
WHERE r.status = #{status}
ORDER BY r.apply_time DESC
LIMIT #{offset}, #{pageSize}
